# Generated by Django data migration to publish the 5 seeded Great Barrier Reef MarineSpecies records

from django.db import migrations

GBR_SPECIES_SLUGS = [
    "amphiprion-percula",
    "acropora-millepora",
    "green-sea-turtle",
    "dugong",
    "halophila-ovalis",
]


def publish_gbr_marine_species(apps, schema_editor):
    MarineSpecies = apps.get_model("explorer", "MarineSpecies")
    MarineSpecies.objects.filter(slug__in=GBR_SPECIES_SLUGS).update(is_published=True)


def unpublish_gbr_marine_species(apps, schema_editor):
    MarineSpecies = apps.get_model("explorer", "MarineSpecies")
    MarineSpecies.objects.filter(slug__in=GBR_SPECIES_SLUGS).update(is_published=False)


class Migration(migrations.Migration):

    dependencies = [
        ("explorer", "0007_seed_gbr_marine_species"),
    ]

    operations = [
        migrations.RunPython(
            publish_gbr_marine_species,
            reverse_code=unpublish_gbr_marine_species,
        ),
    ]

